//! B-635: D-756, Fractal Noise's base cell matches After Effects' size: Scale 100 is a 66.7-pixel
//! cell, the noise worked at c = size / 1.5. Turbulent Noise keeps its size as the cell.
//!
//! Writes `verification/B-635_fractal_size_table.md`. The pixel numbers are the reference's
//! (`tools/fractal_noise_reference.py`, `tools/float_depth_reference.py`), regenerated by D-756;
//! the cell widths are counted here on Block noise of one octave, whose cells are flat.

mod effect_table;

use std::fs;

use effect_table::{both, repo, Table, MAIN};
use serde_json::{json, Value as J};

use anime_compositor::compose::render_frame;
use anime_compositor::diagnostics::FrameLog;
use anime_compositor::gpu::Gpu;
use anime_compositor::model::Id;
use anime_compositor::persist;
use anime_compositor::preview::PreviewQuality;

const WIDE: usize = 400;

/// A white 400 by 8 solid under one effect of `type_id` with `parameters`.
fn shot(type_id: &str, parameters: J) -> String {
    let t = |v: J| json!({"base": v, "keyframes": []});
    json!({
        "schema_version": 0, "project_id": "proj-b635",
        "color_settings": {"working_space": "linear-srgb", "alpha_mode": "premultiplied"},
        "assets": [],
        "compositions": [{
            "id": MAIN, "name": MAIN, "width": WIDE, "height": 8, "pixel_aspect_ratio": 1,
            "frame_rate": {"numerator": 24, "denominator": 1}, "start_frame": 0,
            "duration_frames": 1, "work_area": {"start_frame": 0, "end_frame_exclusive": 1},
            "layer_order": ["white"],
            "layers": [{
                "id": "white", "kind": "solid", "name": "white", "enabled": true, "locked": false,
                "in_frame": 0, "out_frame": 1,
                "solid": {"color": [1, 1, 1], "width": WIDE, "height": 8},
                "transform": {
                    "anchor": t(json!([200, 4])), "position": t(json!([200, 4])),
                    "scale": t(json!([100, 100])), "rotation": t(json!(0)), "opacity": t(json!(1))
                },
                "masks": [], "matte": null, "blend_mode": "normal",
                "effects": [{"instance_id": "f", "type_id": type_id, "enabled": true, "parameters": parameters}]
            }]
        }]
    })
    .to_string()
}

/// Block noise of one octave at `size`, contrast 50 so no two cells clip to one grey.
fn block(type_id: &str, size: f64) -> String {
    let mut p = json!({"fractal_type": "basic", "noise_type": "block", "invert": "off", "size": size,
        "scale_width": 100, "scale_height": 100, "offset": [0, 0], "complexity": 1, "contrast": 50, "brightness": 0,
        "evolution": 30, "seed": 7, "opacity": 100, "blend": "normal"});
    if type_id == "core.fractal_noise" {
        for (k, v) in [("speed", json!(0)), ("dark_color", json!("#000000")), ("light_color", json!("#ffffff"))] {
            p[k] = v;
        }
    }
    shot(type_id, p)
}

/// The widths of the runs of one grey along row 4, the first and last (cut by the edges) left out.
fn cells(project: &str) -> Vec<usize> {
    let loaded = persist::load_str(project).expect("the shot reads");
    let mut log = FrameLog::new(8);
    let f = render_frame(loaded.document.project(), &Id::new(MAIN), 0, std::path::Path::new("."), 64, &mut log)
        .expect("the shot draws");
    let row: Vec<f32> = (0..WIDE).map(|x| f.pixel(x, 4)[0]).collect();
    let mut runs = vec![1usize];
    for x in 1..WIDE {
        if row[x] == row[x - 1] {
            *runs.last_mut().unwrap() += 1;
        } else {
            runs.push(1);
        }
    }
    runs[1..runs.len() - 1].to_vec()
}

#[test]
fn b635_fractal_size() {
    let mut t = Table::new(
        "fractal_noise",
        "# B-635: Fractal Noise's base cell matches After Effects' size (D-756)\n\n\
         Fractal Noise's noise is now worked at two thirds of its size, c = size / 1.5, so Scale 100 \
         draws a 66.7-pixel cell, After Effects' own (measured on four creators' Block noise: 66 to 68 \
         pixels in After Effects against 99 in ours before). Turbulent Noise keeps its size as the \
         cell. The cell widths below are counted on a 400-pixel-wide Block noise of one octave, whose \
         cells are flat; the fixtures' numbers are the reference's, regenerated by D-756.\n",
    );

    t.heading("The cell, counted in pixels along a row of Block noise");
    for (type_id, name, size, lo, hi) in [
        ("core.fractal_noise", "Fractal Noise", 100.0, 66, 67),
        ("core.fractal_noise", "Fractal Noise", 150.0, 100, 100),
        ("core.fractal_noise", "Fractal Noise", 30.0, 20, 20),
        ("core.turbulent_noise", "Turbulent Noise, unchanged", 100.0, 100, 100),
    ] {
        let runs = cells(&block(type_id, size));
        let ok = !runs.is_empty() && runs.iter().all(|w| (lo..=hi).contains(w));
        let want = if lo == hi { format!("{lo}") } else { format!("{lo} or {hi}") };
        t.row(
            &format!("{name} at size {size}: every whole cell is {want} pixels wide"),
            &format!("{runs:?}"),
            ok,
        );
    }
    let fractal = cells(&block("core.fractal_noise", 150.0));
    let turbulent = cells(&block("core.turbulent_noise", 100.0));
    t.row(
        "Fractal Noise at size 150 draws Turbulent Noise's cells at size 100",
        &format!("{fractal:?} and {turbulent:?}"),
        fractal == turbulent,
    );

    t.heading("The fixtures, at the reference's new numbers (tolerance 2e-5)");
    // 022, 024 and 033 were superseded by D-318 and D-326 (`b71_fractal_noise`); none moved.
    t.fixtures_numbered("expected_fractal_noise.json", 1..=21);
    t.fixtures_numbered("expected_fractal_noise.json", 23..=23);
    t.fixtures_numbered("expected_fractal_noise.json", 25..=28);
    t.fixtures_numbered("expected_fractal_noise_d318.json", 29..=32);
    t.fixtures("expected_fractal_noise_d326.json");

    t.heading("An old project");
    let file = repo("Fixtures/fractal_noise/fx_fractal_001.json");
    let old = persist::load(&file).expect("fx_fractal_001.json opens");
    let on_open: Vec<String> = old.warnings.iter().map(|d| d.id.as_str().to_string()).collect();
    t.row(
        "fx_fractal_001.json, saved before D-756, opens with no warning",
        &format!("{on_open:?}"),
        on_open.is_empty(),
    );
    let written: J = serde_json::from_str(&fs::read_to_string(&file).unwrap()).unwrap();
    let same = effect_table::same_json(&effect_table::saved(&old), &written);
    t.row(
        "and saves back holding what it held: its size is still 100, nothing added",
        if same { "the same" } else { "differs" },
        same,
    );
    let mut log = FrameLog::new(8);
    let _ = render_frame(old.document.project(), &Id::new(MAIN), 4, &t.root, 64, &mut log);
    let at_frame: Vec<String> = log.finish().iter().map(|d| d.id.as_str().to_string()).collect();
    t.row(
        "and draws frame 4 with no warning: the finer cell is the rule, not a fallback",
        &format!("{at_frame:?}"),
        at_frame.is_empty(),
    );

    t.heading("On the card against the processor: within 1 level of 255");
    let mut gpu = Gpu::new().expect("a usable card");
    let mut cases: Vec<(String, anime_compositor::model::Project, std::path::PathBuf)> = Vec::new();
    for (name, project) in [
        ("Block noise at size 100", block("core.fractal_noise", 100.0)),
        ("Block noise at size 30", block("core.fractal_noise", 30.0)),
        ("Turbulent Noise's Block noise at size 100", block("core.turbulent_noise", 100.0)),
    ] {
        let p = persist::load_str(&project).unwrap().document.project().clone();
        cases.push((name.to_string(), p, std::path::PathBuf::from(".")));
    }
    for n in [1u32, 3, 6, 9, 16, 20] {
        let name = format!("fx_fractal_{n:03}.json");
        let p = t.load(&name).document.project().clone();
        cases.push((name, p, t.root.clone()));
    }
    for (name, project, root) in &cases {
        let (mut largest, mut refused, mut agree) = (0, false, true);
        for quality in [PreviewQuality::Full, PreviewQuality::Draft] {
            let (d, r, a, b) = both(&mut gpu, project, &Id::new(MAIN), root, 0, quality);
            largest = largest.max(d.0);
            refused |= r;
            agree &= a == b;
        }
        t.row(
            &format!("{name}, frame 0 at Full and Draft"),
            &format!("largest difference {largest} of 255; refused by the card: {refused}; the same warnings: {agree}"),
            largest <= 1 && !refused && agree,
        );
    }

    t.finish("B-635_fractal_size_table.md");
}
